// 🎯 Cross-Language Data Pipeline Demo
//
// This notebook demonstrates seamless data interchange
// between JavaScript, Python, and Rust.
//
// Data flows:
// JS (generate) → Python (analyze) → Rust (optimize) → JS (visualize)

display({
  title: '📊 Multi-Language Data Pipeline',
  languages: ['JavaScript', 'Python', 'Rust'],
  features: [
    'Zero-copy data transfer (with SharedArrayBuffer)',
    'Automatic format conversion',
    'Type-safe interchange'
  ]
});

// 📊 Step 1: Generate sample data in JavaScript

// Simulate sensor readings over time
const sensorData = Array.from({length: 200}, (_, i) => ({
  timestamp: Date.now() + i * 1000,
  temperature: 20 + Math.sin(i / 10) * 5 + Math.random() * 2,
  humidity: 50 + Math.cos(i / 15) * 10 + Math.random() * 5,
  sensor_id: `sensor_${i % 5}`
}));

console.log(`✓ Generated ${sensorData.length} sensor readings`);
console.log('Sample:', sensorData.slice(0, 3));

// This will be automatically exported as Arrow table
// and available to the next cell
sensorData;

