// 📈 Step 5: Visualize results in JavaScript

// All previous results are available:
// - sensorData (from cell 2)
// - sensor_stats (from cell 3)
// - cleaned data (from cell 4)

// Create summary visualization
const summary = {
  total_readings: sensorData.length,
  sensors_analyzed: Object.keys(sensor_stats).length,
  average_temp: Object.values(sensor_stats)
    .reduce((sum, s) => sum + s.mean, 0) / Object.keys(sensor_stats).length,
  data_quality: `${((clean_count / original_count) * 100).toFixed(1)}% clean`,
};

console.log('📊 Pipeline Summary:');
console.log(`  Total Readings: ${summary.total_readings}`);
console.log(`  Sensors: ${summary.sensors_analyzed}`);
console.log(`  Avg Temperature: ${summary.average_temp.toFixed(2)}°C`);
console.log(`  Data Quality: ${summary.data_quality}`);

// Create a simple histogram
const histogram = {};
for (const temp of temperatures) {
  const bucket = Math.floor(temp);
  histogram[bucket] = (histogram[bucket] || 0) + 1;
}

display({
  summary,
  histogram,
  message: '✓ Pipeline complete! Data flowed seamlessly through JS → Python → Rust → JS'
});

// 💡 What Just Happened?
//
// 1. JavaScript generated sensor data (Arrow format)
// 2. Python received it automatically, computed statistics (JSON format)
// 3. Python cleaned the data, created NumPy arrays (NumPy format)
// 4. Rust received arrays for high-performance computation (zero-copy!)
// 5. JavaScript visualized all results (automatic deserialization)
//
// All data transfer was AUTOMATIC:
// - No manual serialization code
// - No format conversions
// - No copying (with SharedArrayBuffer)
//
// The notebook tracked dependencies via the DAG:
//
//  ┌────────────┐
//  │ JS: Generate│
//  └──────┬─────┘
